/bin/bash -lc "python - <<'PY'
from openpyxl import load_workbook
from pathlib import Path
for p in [Path('inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_179-P1.xlsx'), Path('inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_380-P.xlsx')]:
 wb=load_workbook(p,read_only=True,data_only=True)
 print('\\n',p.name, wb.sheetnames)
 for ws in wb.worksheets:
  print(ws.title, ws.max_row,ws.max_column)
  for row in ws.iter_rows(min_row=1,max_row=min(5,ws.max_row),values_only=True): print(row[:12])
PY"

