item.command:
/bin/bash -lc "python - <<'PY'
import csv
p='galaxy_downloads/carriers_concat.tsv'
with open(p,newline='') as f:
 for row in csv.reader(f,delimiter='\\t'):
  if len(row)>=19 and row[13]=='splice_region_variant':
   try:v=float(row[9])
   except:continue
   if v<.3: print([row[i] for i in [0,1,4,9,12,13,14,15,16,17,18]])
PY"

/bin/bash -lc "python - <<'PY'
import csv
p='galaxy_downloads/carriers_concat.tsv'
with open(p,newline='') as f:
 for row in csv.reader(f,delimiter='\\t'):
  if len(row)>=19 and row[13]=='splice_region_variant':
   try:v=float(row[9])
   except:continue
   if v<.3: print([row[i] for i in [0,1,4,9,12,13,14,15,16,17,18]])
PY"

